import{_ as a,c as o,o as t,ag as i}from"./chunks/framework.B-XtCDNB.js";const g=JSON.parse(`{"title":"6. Other Tools","description":"6. Other Tools 6.1. vapigen vapigen is a tool to make bindings. It creates VAPI files from a library's metadata and any extra information required. The entry point is Vala.VAPIGen.main ()...","frontmatter":{"prev":{"text":"5. Internal libgee","link":"/guides/compiler-guide/05-00-internal-libgee"},"next":{"text":"7. Testing","link":"/guides/compiler-guide/07-00-testing"}},"headers":[],"relativePath":"guides/compiler-guide/06-00-other-tools.md","filePath":"guides/compiler-guide/06-00-other-tools.md","lastUpdated":1786109715000}`),d={name:"guides/compiler-guide/06-00-other-tools.md"};function r(c,e,n,s,l,h){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="_6-other-tools" tabindex="-1">6. Other Tools <a class="header-anchor" href="#_6-other-tools" aria-label="Permalink to &quot;6. Other Tools&quot;">​</a></h1><h2 id="_6-1-vapigen" tabindex="-1">6.1. vapigen <a class="header-anchor" href="#_6-1-vapigen" aria-label="Permalink to &quot;6.1. vapigen&quot;">​</a></h2><p><code>vapigen</code> is a tool to make bindings. It creates VAPI files from a library&#39;s metadata and any extra information required.</p><p>The entry point is <code>Vala.VAPIGen.main ()</code> (<code>vapigen/valavapigen.vala</code>), which parses the command line options (such as <code>--library</code>, <code>--pkg</code>, <code>--vapidir</code>, <code>--girdir</code> and <code>--metadatadir</code>) then creates a <code>Vala.VAPIGen</code> instance and calls <code>Vala.VAPIGen.run ()</code>.</p><h3 id="_6-1-1-how-it-works" tabindex="-1">6.1.1. How It Works <a class="header-anchor" href="#_6-1-1-how-it-works" aria-label="Permalink to &quot;6.1.1. How It Works&quot;">​</a></h3><h4 id="_6-1-1-1-setting-up-the-code-context" tabindex="-1">6.1.1.1. Setting Up the Code Context <a class="header-anchor" href="#_6-1-1-1-setting-up-the-code-context" aria-label="Permalink to &quot;6.1.1.1. Setting Up the Code Context&quot;">​</a></h4><p>A new <code>Vala.CodeContext</code> (<code>vala/valacodecontext.vala</code>) is created and pushed onto the context stack. The <code>vapidir</code>, <code>girdir</code> and <code>metadatadir</code> directories passed on the command line are assigned to it, and the target profile is set to <code>Profile.GOBJECT</code>, which makes the standard GObject packages available unless <code>--nostdpkg</code> is given.</p><h4 id="_6-1-1-2-loading-packages" tabindex="-1">6.1.1.2. Loading Packages <a class="header-anchor" href="#_6-1-1-2-loading-packages" aria-label="Permalink to &quot;6.1.1.2. Loading Packages&quot;">​</a></h4><p>Package dependencies are loaded from <code>.deps</code> files:</p><ul><li>For every source ending in <code>.gi</code>, a matching <code>.deps</code> file (same name, <code>.deps</code> extension) is loaded via <code>Vala.CodeContext.add_packages_from_file ()</code>.</li><li>A <code>.deps</code> file named after the <code>--library</code> option is also loaded, since <code>--library</code> is required for a GIR-based binding.</li><li>Any packages passed with <code>--pkg</code> are added individually with <code>Vala.CodeContext.add_external_package ()</code>.</li></ul><h4 id="_6-1-1-3-adding-source-files" tabindex="-1">6.1.1.3. Adding Source Files <a class="header-anchor" href="#_6-1-1-3-adding-source-files" aria-label="Permalink to &quot;6.1.1.3. Adding Source Files&quot;">​</a></h4><p>Each file passed on the command line is added to the code context as a <code>Vala.SourceFile</code> with the type <code>SourceFileType.PACKAGE</code>, via <code>Vala.CodeContext.add_source_file ()</code>. Sources that do not exist on disk are reported as errors.</p><h4 id="_6-1-1-4-parsing" tabindex="-1">6.1.1.4. Parsing <a class="header-anchor" href="#_6-1-1-4-parsing" aria-label="Permalink to &quot;6.1.1.4. Parsing&quot;">​</a></h4><p>The source files are handed to three parsers in turn, in the following order:</p><ol><li><code>Vala.Parser</code> (<code>vala/valaparser.vala</code>) parses any <code>.vapi</code> files among the sources.</li><li><code>Vala.GirParser</code> (<code>vala/valagirparser.vala</code>) parses <code>.gir</code> files, applying any matching <code>.metadata</code> files found via the <code>metadatadir</code> paths.</li><li><code>Vala.GIdlParser</code> (<code>vapigen/valagidlparser.vala</code>) parses the legacy <code>.gi</code> format.</li></ol><p>After each parsing stage, <code>vapigen</code> bails out early if the code context has recorded any errors.</p><h4 id="_6-1-1-5-semantic-check" tabindex="-1">6.1.1.5. Semantic Check <a class="header-anchor" href="#_6-1-1-5-semantic-check" aria-label="Permalink to &quot;6.1.1.5. Semantic Check&quot;">​</a></h4><p><code>Vala.CodeContext.check ()</code> runs semantic analysis over everything that has been parsed so far, resolving symbols and validating the resulting tree, in the same way the compiler does when building a program.</p><h4 id="_6-1-1-6-writing-the-vapi-file" tabindex="-1">6.1.1.6. Writing the VAPI File <a class="header-anchor" href="#_6-1-1-6-writing-the-vapi-file" aria-label="Permalink to &quot;6.1.1.6. Writing the VAPI File&quot;">​</a></h4><p>Only the source files that were explicitly passed on the command line are marked as <code>SourceFileType.SOURCE</code>; everything else (external packages) stays excluded from the output. A <code>Vala.CodeWriter</code> (<code>vala/valacodewriter.vala</code>) is created with the <code>CodeWriterType.VAPIGEN</code> mode, which writes out a <code>.vapi</code> file named after the <code>--library</code> option (optionally placed in the directory given by <code>--directory</code>).</p><p>If the resulting library name does not match the <code>pkg-config</code> package name declared by a <code>.gir</code> source, a warning is emitted.</p><h2 id="_6-2-vala-gen-introspect" tabindex="-1">6.2. vala-gen-introspect <a class="header-anchor" href="#_6-2-vala-gen-introspect" aria-label="Permalink to &quot;6.2. vala-gen-introspect&quot;">​</a></h2><p><code>vala-gen-introspect</code> is a tool for extracting metainformation about GObject based libraries. Nowadays, the preferred method is to use GObject Introspection instead, as <code>vapigen</code> can use GIR files directly.</p>',23)])])}const m=a(d,[["render",r]]);export{g as __pageData,m as default};
